mapper.select:
SELECT id, knowledge_base_id, document_id, chunk_index, content, metadata, vector_id, content_hash, source_type, 1.0 AS score FROM v5ai_knowledge_chunk WHERE knowledge_base_id IN
#{id}
AND LOWER(content) LIKE LOWER(#{keyword}) ORDER BY id LIMIT #{limit}

SELECT id, knowledge_base_id, document_id, chunk_index, content, metadata, vector_id, content_hash, source_type, keyword_tokens FROM v5ai_knowledge_chunk WHERE
AND JSON_OVERLAPS(keyword_tokens, CAST(#{termsJson} AS JSON)) ORDER BY (
JSON_CONTAINS(keyword_tokens, JSON_QUOTE(#{term}))
) DESC, id
AND keyword_tokens && #{terms, typeHandler=xin.v5ai.nb.rag.core.store.TextArrayTypeHandler} ORDER BY cardinality(ARRAY(SELECT unnest(keyword_tokens) INTERSECT SELECT unnest(#{terms, typeHandler=xin.v5ai.nb.rag.core.store.TextArrayTypeHandler}))) DESC, id
LIMIT #{limit}
